import{_ as a,o as t,c as l,a6 as r}from"./chunks/framework.BrkgobfX.js";const m=JSON.parse('{"title":"回顾","description":"把 Jev 的来龙去脉收成一页：它是什么、两条原理、怎么用、能用在哪，哪些说法已被独立测试印证、哪些仍是官方口径，以及接下来值得盯的几件事。","frontmatter":{"title":"回顾","description":"把 Jev 的来龙去脉收成一页：它是什么、两条原理、怎么用、能用在哪，哪些说法已被独立测试印证、哪些仍是官方口径，以及接下来值得盯的几件事。","source":"https://daiw.org/manual/jev/recap"},"headers":[],"relativePath":"manual/llm/jev/recap.md","filePath":"manual/llm/jev/recap.md"}'),o={name:"manual/llm/jev/recap.md"};function n(d,e,i,s,c,h){return t(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="回顾" tabindex="-1">回顾 <a class="header-anchor" href="#回顾" aria-label="Permalink to &quot;回顾&quot;">​</a></h1><blockquote><p>把 Jev 的来龙去脉收成一页：它是什么、两条原理、怎么用、能用在哪，哪些说法已被独立测试印证、哪些仍是官方口径，以及接下来值得盯的几件事。</p></blockquote><p>七篇读下来，Jev 可以用一句话概括：<strong>把“做选择”从大语言模型里拆出来，交给一个专门的、快而便宜的模型</strong>。它不写字，只按你事先定义的类型给出每个选项的概率（或图像里的目标边界框）。这一篇把全书收成一页。</p><h2 id="它是什么" tabindex="-1">它是什么 <a class="header-anchor" href="#它是什么" aria-label="Permalink to &quot;它是什么&quot;">​</a></h2><ul><li><strong>一个 System One 模型</strong>。借用卡尼曼“快思考 / 慢思考”的说法：Jev 负责窄而快的判断，大语言模型负责生成文本与深度推理，两者分工而不是互相替代（<a href="/Front2Full/manual/llm/jev/system-one">System One：快思考模型</a>）。</li><li><strong>一家刚走出“隐身”的公司的第一个模型家族</strong>。TypeSafe AI 于 2026 年 9 月 15 日发布 Jev（<code>jev-1.13.0</code>）并开放早期访问，随后于 10 月 14 日升级至 <code>Jev 1.14</code>（<code>jev-1.14.0</code>，新增图像输入、第四种原语 <code>Box</code> 与 262k 长上下文模式）；名字致敬提出“杰文斯悖论”的经济学家 Jevons（<a href="/Front2Full/manual/llm/jev/what-is-jev">Jev 是什么</a>）。</li></ul><h2 id="两条原理" tabindex="-1">两条原理 <a class="header-anchor" href="#两条原理" aria-label="Permalink to &quot;两条原理&quot;">​</a></h2><ol><li><strong>并行给出全部答案</strong>。大语言模型要一个 token 接一个 token 地写，每一步都得等上一步；Jev 的输出空间事先定义好，可以一次并行给出。这也是“不会幻觉”这个说法的真实含义：它不会编出选项之外的东西，但仍然可能选错（<a href="/Front2Full/manual/llm/jev/parallel-sampler">原理一：并行采样</a>）。</li><li><strong>把概率当成要负责的东西</strong>。校准的意思是“说 85% 就真有约 85% 对”。官方只说 RLCD 让模型的概率对照真实结果来优化；奖励函数的具体形式（用不用 Brier 这类评分规则）、训练数据怎么造都没有公开，也没公布可靠性图、ECE 这类能直接检验校准的数据（<a href="/Front2Full/manual/llm/jev/rlcd">原理二：RLCD 与概率校准</a>）。</li></ol><h2 id="怎么用、用在哪" tabindex="-1">怎么用、用在哪 <a class="header-anchor" href="#怎么用、用在哪" aria-label="Permalink to &quot;怎么用、用在哪&quot;">​</a></h2><ul><li><strong>调用方式</strong>：一次请求由“材料”（文本或 PNG/JPEG 图像）加“一组带类型的问题”（<code>Choice</code>、<code>Score</code>、<code>Noul</code>、<code>Box</code>）组成，返回每个选项的概率（或归一化边界框坐标）与置信度；按输入 token 计费（$0.042 / 百万 token）、输出免费（<a href="/Front2Full/manual/llm/jev/using-jev">上手</a>）。</li><li><strong>适合的活</strong>：工单分诊与意图路由、Agent 动作审查与模型路由、检索重排、邮件分类这类“从有限选项里挑一个”的判断；官方还用 Doom 和维基竞速做了实时演示（<a href="/Front2Full/manual/llm/jev/applications">应用</a>）。</li></ul><h2 id="哪些已被印证-哪些还只是官方口径" tabindex="-1">哪些已被印证，哪些还只是官方口径 <a class="header-anchor" href="#哪些已被印证-哪些还只是官方口径" aria-label="Permalink to &quot;哪些已被印证，哪些还只是官方口径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>说法</th><th>现状</th></tr></thead><tbody><tr><td>比前沿 LLM 更快、更省</td><td>第一批个人独立测试印证了方向，但幅度比官方数字小得多</td></tr><tr><td>40–200 倍的速度、100 倍的成本优势</td><td>官方口径，只针对“System One 形状”的任务</td></tr><tr><td>已经校准</td><td>官方口径；没有公开的可靠性图或 ECE，独立数据只有样本很小的社区试测</td></tr><tr><td>公开基准上的成绩</td><td>官方刻意不公布；自家评测的参考答案来自别的模型</td></tr><tr><td>架构、参数量、训练数据</td><td>尚未公开；媒体报道里的说法彼此矛盾</td></tr></tbody></table><p>官方文档也坦白列了它的短板：多一层间接的问题容易吃力，理解偏字面，不擅长对数值精度要求高的任务，在边界样本上还对选项排列顺序敏感（<a href="/Front2Full/manual/llm/jev/limits-outlook">局限与展望</a>）。</p><h2 id="接下来值得盯的几件事" tabindex="-1">接下来值得盯的几件事 <a class="header-anchor" href="#接下来值得盯的几件事" aria-label="Permalink to &quot;接下来值得盯的几件事&quot;">​</a></h2><ul><li>有没有论文、技术报告或模型卡；</li><li>有没有独立机构针对 <code>Jev 1.14</code>（包括图像输入与 <code>Box</code> 原语）的大规模评测，尤其是端到端的 Agent 工作流；</li><li>早期访问全面放开后的实际价格与限额；</li><li>非英语场景（包括中文）在 <code>Jev 1.14</code> 升级后的实测表现；</li><li>杰文斯悖论会不会应验：判断变便宜以后，调用量是不是涨得比价格降得还快。</li></ul><h2 id="继续读什么" tabindex="-1">继续读什么 <a class="header-anchor" href="#继续读什么" aria-label="Permalink to &quot;继续读什么&quot;">​</a></h2><ul><li><strong>想弄懂大语言模型为什么只能逐字写</strong>：<a href="https://daiw.org/manual/llm-anatomy" target="_blank" rel="noreferrer">《AI 大模型解构》</a>。</li><li><strong>想看同期另一条前沿方向</strong>：<a href="https://daiw.org/manual/rsi" target="_blank" rel="noreferrer">《RSI 技术探究》</a>——AI 怎样参与改进 AI 自己。</li><li><strong>想看 Agent 是怎么搭起来的</strong>：<a href="https://daiw.org/manual/llm-to-agent" target="_blank" rel="noreferrer">《从 LLM 到 Coding Agent》</a>。</li></ul>',16)])])}const g=a(o,[["render",n]]);export{m as __pageData,g as default};
